// Real jurisdiction escalation logic
const form = $('New Service Attempt Submitted').item.json;
const caseRows = $input.all().map(i => i.json);
const existing = caseRows[0] || {};
const priorAttempts = Number(existing.attempt_count || 0);
const attemptCount = priorAttempts + 1;
const solDate = existing.sol_deadline ? new Date(existing.sol_deadline)
  : (form['SOL Deadline'] ? new Date(form['SOL Deadline']) : null);
const now = new Date();
let daysToSol = null;
if (solDate) daysToSol = Math.ceil((solDate.getTime() - now.getTime()) / 86400000);
const firstAttemptDate = existing.first_attempt_date || now.toISOString();
const daysSinceFirst = Math.floor((now.getTime() - new Date(firstAttemptDate).getTime()) / 86400000);
// Jurisdiction rule: 3+ attempts on different days within 30 days, still not served -> alt-service eligible
const altServiceEligible = attemptCount >= 3 && daysSinceFirst <= 30;
const solUrgent = daysToSol !== null && daysToSol <= 14;
return { json: {
  case_number: form['Case Number'], defendant: form['Defendant Name'],
  address: form['Address Attempted'], outcome_notes: form['Outcome Notes'],
  attempt_count: attemptCount, first_attempt_date: firstAttemptDate,
  days_since_first: daysSinceFirst, sol_deadline: solDate ? solDate.toISOString() : null,
  days_to_sol: daysToSol, sol_urgent: solUrgent, alt_service_eligible: altServiceEligible,
  already_authorized: existing.alt_service_authorized === true,
}};

// Real template-fill logic, no AI needed for a legal boilerplate document
const j = $input.item.json;
const method = j.case_status === 'served' ? 'personal service' : 'substitute/alternate service (court-authorized)';
const text = `AFFIDAVIT OF SERVICE\n\n`
  + `Case No.: ${j.case_number}\n`
  + `Defendant: ${j.defendant}\n`
  + `Address: ${j.address}\n`
  + `Total attempts: ${j.attempt_count}\n`
  + `Method of service: ${method}\n`
  + `I certify the foregoing is true and correct under penalty of perjury.`;
return { json: { ...j, affidavit_text: text, affidavit_filename: `affidavit_${j.case_number}.txt` } };
